CREATE TABLE public.quick_chats (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sender_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, receiver_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, content TEXT NOT NULL, is_edited BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now() NOT NULL, updated_at TIMESTAMPTZ DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.quick_chats TO authenticated; GRANT ALL ON public.quick_chats TO service_role; ALTER TABLE public.quick_chats ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can read their own chats" ON public.quick_chats FOR SELECT TO authenticated USING (auth.uid() = sender_id OR auth.uid() = receiver_id); CREATE POLICY "Users can insert their own messages" ON public.quick_chats FOR INSERT TO authenticated WITH CHECK (auth.uid() = sender_id); CREATE POLICY "Users can update their own messages" ON public.quick_chats FOR UPDATE TO authenticated USING (auth.uid() = sender_id) WITH CHECK (auth.uid() = sender_id); CREATE POLICY "Users can delete their own messages" ON public.quick_chats FOR DELETE TO authenticated USING (auth.uid() = sender_id);